function cacheGetAndSet(key, supplyFunc, requestUpdate) {
	try {
		var entry = null;
		try { entry = cache.getFromMemory(key); } catch(e) { entry = null; }
		if (!entry) {
			try { var disk = cache.get(key); if (disk) { try { entry = JSON.parse(disk); } catch(e) { entry = null; } } } catch(e) { entry = null; }
		}
		var now = Date.now();
		var isExpired = entry && entry.t && (now >= entry.t + cacheTempSeconds);
		requestUpdate = requestUpdate || isExpired;
		if (!entry || requestUpdate) {
			var value = null;
			try { value = supplyFunc(); } catch(e) { value = null; }
			if (value != null && value !== '') {
				entry = {t: now, v: value};
				try { cache.putMemory(key, entry); } catch(e) {}
				try { cache.put(key, JSON.stringify(entry), cacheSaveSeconds); } catch(e) {}
			} else { return null; }
