		}
		if (arResp) {
			try {
				let ar = JSON.parse(arResp);
				if (ar && ar.illust && ar.illust.meta_single_page && ar.illust.meta_single_page.original_image_url) {
					url = ar.illust.meta_single_page.original_image_url;
				} else if (ar && ar.illust && ar.illust.meta_pages && ar.illust.meta_pages[order-1]) {
					url = ar.illust.meta_pages[order-1].image_urls.original;
				}
			} catch(e) {}
		}
	}
	if (url && url != 'null' && order > 1) {
		url = url.replace(/_p0/, '_p' + (order - 1));
	}
	let re = new RegExp('\\[pixivimage\\:' + illustId + (m[2] ? '\\-' + m[2] : '') + '\\]');
	tt = tt.replace(re, makeImg(url, 'Pixiv 插画'));
	}
tt = tt.replaceAll('[newpage]','\n—换页符—\n');
