        'excited3': 309, 'love3': 310, 'normal4': 401, 'surprise4': 402, 'series4': 403,
        'love4': 404, 'shine4': 405, 'sweet4': 406, 'shame4': 407, 'sleep4': 408,
        'heart': 501, 'teardrop': 502, 'star': 503
    };
    tt = tt.replace(/\(([a-zA-Z0-9_]+)\)/g, function(match, key) {
        if (emojiMap.hasOwnProperty(key)) {
            let imgUrl = 'https://s.pximg.net/common/images/emoji/' + emojiMap[key] + '.png';
            return '<img src="' + imgUrl + ',{\'style\':\'text\'}"/>';
        }
        return match;
    });
}
if (source.get('showSyntax') != '0') {
    tt = tt.replace(/\[chapter:(.*?)\]/g, '<h3>$1</h3>');
    tt = tt.replace(/\[jump:(\d+)\]/g, '跳转至第 $1 节');
}
if (source.get('showCaption') != '0') {
