    if (cap) {
        let capHtml = cap.replace(/(?:<br \/>)+/g, '</p><p>');
        let mode = parseInt(source.get('dividerMode'));
        if (isNaN(mode)) mode = 3;
        let divider = '';
        if (mode > 0) {
            let styles = [
                '',
                '<p>━━━━━━━━━━━━━━━━</p>',
                '<p>━━━ (=^･^=) ━━━ ( =^･^= ) ━━━</p>',
                '<p>━━━ ฅ(^ω^ฅ) ━━━ ฅ(^ω^ฅ) ━━━</p>',
                '<p>—— 这 · 里 · 是 · 分 · 割 · 线 ——</p>'
            ];
            divider = styles[mode] || '';
        }
        tt = '<p>' + capHtml + '</p>' + divider + tt;
    }
}
if (source.get('rubyReplace') != '0') {
    tt = tt.replace(/\[\[rb:(.*?)>(.*?)\]\]/g, '$1（$2）');
