source.jsLib:
var hosts = [
    "https://38.34.172.127",
    "https://www.yybsw.com"
];

function getHosts() {
    return hosts;
}

function getServerHost() {
    var source = this.source;
    try {
        var config = JSON.parse(source.getVariable());
        if (config && config[0] && config[0].host) {
            return config[0].host;
        }
        return getHosts()[0];
    } catch (e) {
        return getHosts()[0];
    }
}

function getConfig() {
    var source = this.source;
    try {
        var configStr = source.getVariable();
        if (!configStr || configStr.trim() === "") {
            return { host: getHosts()[0] };
        }
        var config = JSON.parse(configStr);
        if (!config || !config.join || config.length === 0) {
            return { host: getHosts()[0] };
        }
        return config[0] || { host: getHosts()[0] };
    } catch (e) {
        return { host: getHosts()[0] };
    }
}

function setConfig(key, value) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        config[key] = value;
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function setConfigs(obj) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        for (var k in obj) {
            if (obj.hasOwnProperty(k)) {
                config[k] = obj[k];
            }
        }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

